/*
    SHADER 101: CHROMATIC COORDINATES

    A coordinate experiment built from distance, angle, and time.

    Each pixel starts as a screen coordinate. We center that coordinate,
    measure its distance and angle from the center, then use those values
    to create animated spiral waves and separated color channels.

    Try changing:

    - radius * 18.0
      Controls the number of wave bands.

    - angle * 4.0
      Controls how strongly the bands twist into a spiral.

    - iTime * 0.7
      Controls the animation speed.

    - 2.1 and 4.2
      Offset the green and blue channels, creating the chromatic effect.
*/


#define PI 3.14159265359

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Convert the current pixel from screen coordinates into 0–1 UV space.
    vec2 uv = fragCoord / iResolution.xy;

    // Move the origin to the center and preserve circular proportions.
    vec2 p = uv - 0.5;
    p.x *= iResolution.x / iResolution.y;

    // Measure the pixel's distance from the center and its angle around it.
    float radius = length(p);
    float angle = atan(p.y, p.x);

    // Distance creates the rings. Angle bends them into a spiral.
    float wave = sin(
        radius * 18.0
        - iTime * 0.7
        + angle * 4.0
    );

    // Sample the same pattern three times with shifted phases.
    // The phase offsets separate the red, green, and blue channels.
    float red = 0.5 + 0.5 * sin(wave * PI + radius * 5.0);
    float green = 0.5 + 0.5 * sin(wave * PI + radius * 5.0 + 2.1);
    float blue = 0.5 + 0.5 * sin(wave * PI + radius * 5.0 + 4.2);

    vec3 color = vec3(red, green, blue);

    // Darken the outer edges and keep attention near the center.
    float vignette = 1.0 - smoothstep(0.25, 0.85, radius);
    color *= vignette;

    // Add a subtle glow at the center of the coordinate field.
    color += 0.12 * exp(-radius * 5.0);

    // Output the final color for this pixel.
    fragColor = vec4(color, 1.0);
}

/*
    SHADER 101: DISTANCE FIELDS

    A shape can be described by the distance from each pixel
    to its surface.

    For a circle:
        length(p) - radius

    The result is:
    - negative inside the circle
    - zero on the edge
    - positive outside the circle

    One distance value can control nearly every visual property
    of a 2D shape: its fill, outline, glow, and color.

    Try changing:
    - 0.28  : circle size
    - 0.015 : outline thickness
    - 3.0   : glow falloff
*/

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Center the coordinate system and preserve proportions.
    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Circle signed distance field:
    // negative inside, zero on the surface, positive outside.
    float d = length(p) - 0.28;

    // Use the sign of the distance to fill the inside of the shape.
    float fill = step(d, 0.0);

    // Use the absolute distance to isolate a thin surface outline.
    float outline = 1.0 - smoothstep(0.0, 0.015, abs(d));

    // Make the distance fade smoothly into an outer glow.
    float glow = exp(-abs(d) * 3.0);

    // Animate the surface color by offsetting the RGB channels.
    vec3 surfaceColor = 0.5 + 0.5 * cos(
        iTime + vec3(0.0, 2.0, 4.0)
    );

    vec3 color = vec3(0.01, 0.015, 0.03);

    // Apply the distance field as a solid interior.
    color += fill * surfaceColor * 0.35;

    // Apply the same distance field as a bright surface rim.
    color += outline * vec3(0.4, 0.8, 1.0);

    // Apply the same distance field as a soft surrounding glow.
    color += glow * vec3(0.03, 0.15, 0.3);

    fragColor = vec4(color, 1.0);
}

/*
    SHADER 101: BOOLEAN GEOMETRY

    Distance fields let us describe simple shapes mathematically.

    Boolean operations let us combine those shapes:

    - min(a, b)  : union — keep either shape
    - max(a, -b) : subtraction — cut one shape from another

    This shader creates a moving crescent by subtracting
    one circle from another.

    Try changing:
    - 0.30 : main circle size
    - 0.20 : cutout circle size
    - 0.12 : cutout offset
    - 0.7  : movement speed
*/

float circleSDF(vec2 p, float radius)
{
    // Negative inside, zero on the edge, positive outside.
    return length(p) - radius;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Center the coordinate system and preserve proportions.
    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // First distance field: the main circle.
    float mainCircle = circleSDF(p, 0.30);

    // Second distance field: the animated cutting circle.
    vec2 cutoutOffset = vec2(
        0.12 + sin(iTime * 0.7) * 0.025,
        0.02
    );

    float cutoutCircle = circleSDF(p - cutoutOffset, 0.20);

    // Subtract the second shape from the first.
    // max(a, -b) keeps the main circle but removes the cutout.
    float crescent = max(mainCircle, -cutoutCircle);

    // Use the final distance to create the interior.
    float fill = smoothstep(0.01, -0.01, crescent);

    // Isolate the surface of the combined shape.
    float outline = 1.0 - smoothstep(
        0.0,
        0.012,
        abs(crescent)
    );

    // Create a soft glow around the surface.
    float glow = exp(-abs(crescent) * 8.0);

    // Add a gentle vertical color gradient to the crescent.
    float colorShift = 0.5 + 0.5 * p.y / 0.35;

    vec3 surfaceColor = mix(
        vec3(0.05, 0.25, 0.75),
        vec3(0.20, 0.85, 1.00),
        clamp(colorShift, 0.0, 1.0)
    );

    // Deep blue background with a subtle central atmosphere.
    vec3 color = vec3(0.005, 0.01, 0.03);
    color += vec3(0.015, 0.04, 0.10) * exp(-length(p) * 3.0);

    // Fill, outline, and glow all come from the combined distance field.
    color += fill * surfaceColor * 0.55;
    color += outline * vec3(0.35, 0.85, 1.0);
    color += glow * vec3(0.03, 0.20, 0.55);

    fragColor = vec4(color, 1.0);
}

/*
    SHADER 101: REPETITION

    `fract()` repeats coordinates into tiles.

    Instead of drawing one shape across the whole screen,
    we create one local shape inside a single tile.
    The repeated coordinate space automatically copies it.

    Try changing:

    - 3.2  : tile density
    - 0.30 : portal size
    - 0.08 : inner opening size
    - 0.6  : animation speed
*/

mat2 rotate(float angle)
{
    float s = sin(angle);
    float c = cos(angle);

    return mat2(c, -s, s, c);
}

float roundedBox(vec2 p, vec2 size, float radius)
{
    vec2 q = abs(p) - size + radius;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - radius;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Center the screen and preserve proportions.
    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Repeat the coordinate space into equal tiles.
    vec2 cellId = floor(p * 3.2);
    vec2 q = fract(p * 3.2) - 0.5;

    // Rotate the local shape very slightly over time.
    q *= rotate(iTime * 0.12);

    // Create a rounded diamond-like outer portal.
    float outer = roundedBox(q, vec2(0.29), 0.075);

    // Cut a smaller opening out of its center.
    float inner = roundedBox(q, vec2(0.105), 0.035);

    // Boolean subtraction: outer shape minus inner opening.
    float portal = max(outer, -inner);

    // Fill the portal body.
    float fill = smoothstep(0.015, -0.015, portal);

    // Bright edge around the complete shape.
    float edge = 1.0 - smoothstep(
        0.0,
        0.018,
        abs(portal)
    );

    // Traveling color variation shared across the pattern.
    float flow = 0.5 + 0.5 * sin(
        q.x * 10.0
        + q.y * 7.0
        + iTime * 1.2
    );

    vec3 portalColor = mix(
        vec3(0.08, 0.12, 0.75),
        vec3(0.05, 0.85, 0.95),
        flow
    );

    // Dark atmospheric background.
    vec3 color = vec3(0.004, 0.006, 0.025);

    // Subtle tile-local atmosphere.
    color += exp(-length(q) * 3.0) * vec3(0.015, 0.04, 0.13);

    // Add the repeated portal shapes.
    color += fill * portalColor * 0.45;
    color += edge * vec3(0.25, 0.75, 1.0);

    // Warm glow inside each opening.
    float opening = 1.0 - smoothstep(0.0, 0.11, length(q));
    color += opening * vec3(0.35, 0.08, 0.025) * 0.35;

    // Add a gentle diagonal light sweep across the whole composition.
    float sweep = exp(
        -abs(p.x + p.y - sin(iTime * 0.4) * 0.8) * 4.0
    );

    color += sweep * vec3(0.04, 0.10, 0.25);

    fragColor = vec4(color, 1.0);
}
